201	#[serde(rename_all = "camelCase", deny_unknown_fields)]
202	pub struct ApprovalRequest {
203	    did: String,
204	    signing_key: String,
205	    request_id: String,
206	    /// `"approve"` or `"deny"` — bound into the signed envelope so a captured denial cannot be
207	    /// replayed as an approval.
