1	// pattern: Imperative Shell
2	//
3	// The sending side of the notification relay: turn a notification into one HPKE-sealed,
4	// length-quantized payload *per registered device* and hand each to the relay worker.
5	//
6	// Three properties this module is responsible for, in the order they matter:
7	//
8	// 1. **Confidentiality.** The relay and Apple both handle the payload, and neither may read
9	//    it. Every send is sealed to one specific device's notification public key.
10	// 2. **Authenticity.** HPKE `mode_auth` proves the payload came from this instance's sender
11	//    key. A malicious relay can drop or duplicate a push; it cannot author one that renders
12	//    as genuine.
13	// 3. **Metadata minimization.** Ciphertext length is visible to everyone on the path, and
14	//    notification *length* betrays notification *kind*. Every payload is padded up to a
15	//    bucket before sealing.
16	//
17	// Fan-out is one seal per registration, never one seal reused: HPKE seals to a single
18	// recipient key, and reusing an encapsulated key across devices would be a different (and
19	// weaker) protocol.
20	//
21	// Nothing here is fallible from a caller's perspective. Every path ends in an enqueue or a
22	// log line, because a notification is a courtesy: a missed banner is recovered the next time
23	// the app talks to Custos, whereas a trigger that fails because a push relay is unwell has
24	// turned a courtesy into an outage.
25	
26	use serde::Serialize;
27	use zeroize::Zeroizing;
28	
29	use crate::app::AppState;
30	use crate::db::notifications as store;
31	use crate::notify_relay_client::{NotifyJob, RegistrationOwner};
32	
33	/// The plaintext a device's Notification Service Extension decrypts and renders.
34	///
35	/// Serialized camelCase, matching the wallet's decoder. `pad` is the length-quantizing
36	/// filler; it is meaningless to the reader and is the last field so the arithmetic below can
37	/// reason about it as a suffix.
38	#[derive(Debug, Clone, Serialize)]
39	#[serde(rename_all = "camelCase")]
40	pub struct NotificationPayload {
41	    /// Machine-readable kind, e.g. `agent_claim_pending`. The app routes on this.
42	    #[serde(rename = "type")]
43	    pub kind: &'static str,
44	    pub title: String,
45	    pub body: String,
46	    #[serde(skip_serializing_if = "Option::is_none")]
47	    pub data: Option<serde_json::Value>,
48	    /// Spaces, sized so the serialized APNs body lands on a padding bucket.
49	    pub pad: String,
50	}
51	
52	impl NotificationPayload {
53	    /// A payload with no padding yet — [`seal_for`] computes and applies it.
54	    pub fn new(kind: &'static str, title: impl Into<String>, body: impl Into<String>) -> Self {
55	        Self {
56	            kind,
57	            title: title.into(),
58	            body: body.into(),
59	            data: None,
60	            pad: String::new(),
61	        }
62	    }
63	
64	    /// Attach structured routing data (a claim attempt id, a subject DID, …).
65	    pub fn with_data(mut self, data: serde_json::Value) -> Self {
66	        self.data = Some(data);
67	        self
68	    }
69	}
70	
71	/// Notify every device registered to `did`.
72	///
73	/// Silent and harmless when notifications are unconfigured, when the account has no
74	/// registered devices, or when the relay is unreachable.
75	pub async fn notify_device(state: &AppState, did: &str, payload: NotificationPayload) {
76	    let Some(sender) = state.notify_sender.as_ref() else {
77	        return;
78	    };
79	    let registrations = match store::list_registrations(&state.db, did).await {
80	        Ok(rows) => rows,
81	        Err(e) => {
82	            tracing::warn!(error = %e, "failed to load notification registrations");
83	            return;
84	        }
85	    };
86	    fan_out(state, sender, registrations, payload, |device_id| {
87	        RegistrationOwner::Account {
88	            did: did.to_string(),
89	            device_uuid: device_id,
90	        }
91	    })
92	    .await;
93	}
94	
95	/// Notify every *active* admin-companion device — the operator alert channel.
96	///
97	/// The registration and key-pinning halves ship here; the operator *triggers* that call this
98	/// (labeler flags, health alerts) land with admin-companion adoption, so nothing in-tree
99	/// invokes it yet. Kept rather than deferred because the admin registration route it serves
100	/// is already live — a stored registration nothing can ever send to would be the odder state.
101	#[allow(dead_code)]
102	pub async fn notify_admin_devices(state: &AppState, payload: NotificationPayload) {
103	    let Some(sender) = state.notify_sender.as_ref() else {
104	        return;
105	    };
106	    let registrations = match store::list_active_admin_registrations(&state.db).await {
107	        Ok(rows) => rows,
108	        Err(e) => {
109	            tracing::warn!(error = %e, "failed to load admin notification registrations");
110	            return;
111	        }
112	    };
113	    fan_out(state, sender, registrations, payload, |device_id| {
114	        RegistrationOwner::AdminDevice {
115	            admin_device_id: device_id,
116	        }
117	    })
118	    .await;
119	}
120	
121	async fn fan_out(
122	    state: &AppState,
123	    sender: &crate::notify_relay_client::NotifySender,
124	    registrations: Vec<store::RegistrationRow>,
125	    payload: NotificationPayload,
126	    owner_of: impl Fn(String) -> RegistrationOwner,
127	) {
128	    if registrations.is_empty() {
129	        return;
130	    }
131	
132	    // Load the sealing key once for the whole fan-out. Doing it per device would mean a
133	    // rotation landing mid-fan-out seals some devices under the old key and some under the
134	    // new — both valid, but needlessly hard to reason about when debugging a delivery.
135	    let Some((kid, secret)) = active_sender_key(state).await else {
136	        return;
137	    };
138	
139	    for registration in registrations {
140	        // A registration with no handle has not completed its relay round trip yet (the
141	        // relay was down at registration time, or the job is still queued). There is nothing
142	        // to push to; the next registration attempt mints one.
143	        let Some(handle) = registration.push_handle.clone() else {
144	            continue;
145	        };
146	
147	        let recipient =
148	            match crypto::p256_public_key_from_did_key(&registration.notification_public_key) {
149	                Ok(key) => key,
150	                Err(e) => {
151	                    // Registration validated this key, so reaching here means the stored row is
152	                    // corrupt — worth an error, not a silent skip.
153	                    tracing::error!(error = %e, "stored notification public key is unusable");
154	                    continue;
155	                }
156	            };
157	
158	        let Some(sealed) = seal_for(kid, &secret, &recipient, &payload) else {
159	            continue;
160	        };
161	
162	        // `send` fails only once every receiver is gone, i.e. the worker has stopped. Not
163	        // worth a per-device log line.
164	        sender.send(NotifyJob::Push {
165	            owner: owner_of(registration.device_id),
166	            handle,
167	            kid,
168	            enc: base64url(&sealed.enc),
169	            ct: base64url(&sealed.ct),
170	        });
171	    }
172	}
173	
174	/// Pad, then seal, one payload for one recipient.
175	///
176	/// Returns `None` when the payload cannot be sent — which for v1 means only one thing: it is
177	/// too large for the top padding bucket. We refuse rather than degrade. Sending it unpadded
178	/// would leak the exact length that padding exists to hide, and truncating the body would
179	/// deliver a security notice that no longer says what happened; a dropped banner is the one
180	/// failure mode with no downside beyond the missed banner itself.
181	fn seal_for(
182	    kid: i64,
183	    sender_secret: &[u8; 32],
184	    recipient_public_key: &[u8],
185	    payload: &NotificationPayload,
186	) -> Option<crypto::SealedNotification> {
187	    let pad_len = pad_len_for(kid, payload)?;
188	
189	    let mut padded = payload.clone();
190	    padded.pad = " ".repeat(pad_len);
191	    let plaintext = match serde_json::to_vec(&padded) {
192	        Ok(bytes) => bytes,
193	        Err(e) => {
194	            tracing::error!(error = %e, "failed to serialize a notification payload");
195	            return None;
196	        }
197	    };
198	
199	    match crypto::seal_notification(sender_secret, recipient_public_key, &plaintext) {
200	        Ok(sealed) => Some(sealed),
201	        Err(e) => {
202	            tracing::error!(error = %e, "failed to seal a notification");
203	            None
204	        }
205	    }
206	}
207	
208	/// How many pad bytes make this payload's APNs body land on a bucket.
209	///
210	/// The buckets are defined on the **serialized APNs request body**, because that is the only
211	/// length anyone on the path actually measures. So this models the exact body the relay will
212	/// build (via the shared [`notify_relay::protocol::apns_envelope`]) and works backwards
213	/// through base64url expansion. Sealing is deterministic in length — ciphertext is plaintext
214	/// plus a 16-byte tag, and `enc` is always a 65-byte point — so this needs no trial seal.
215	fn pad_len_for(kid: i64, payload: &NotificationPayload) -> Option<usize> {
216	    let unpadded_plaintext_len = serde_json::to_vec(payload).ok()?.len();
