108	fn map_discovery_error(error: PdsClientError) -> ConsentError {
109	    match error {
110	        PdsClientError::DidNotFound | PdsClientError::InvalidResponse { .. } => {
111	            ConsentError::UnsupportedHost
112	        }
113	        PdsClientError::PdsUnreachable { reason } => {
114	            ConsentError::TransportFailure { message: reason }
115	        }
