123	fn pds_url_is_safe(url: &str) -> bool {
124	    let Ok(url) = url::Url::parse(url) else {
125	        return false;
126	    };
127	    url.scheme() == "https"
128	        || (url.scheme() == "http"
129	            && matches!(
130	                url.host_str(),
131	                Some("localhost") | Some("127.0.0.1") | Some("::1") | Some("[::1]")
132	            ))
133	}
