135	/// Resolve the selected DID's hosting PDS URL, verifying the DID document matches and the endpoint
136	/// is safe to send a request to.
137	async fn resolve_safe_pds(pds_client: &PdsClient, did: &str) -> Result<String, ConsentError> {
138	    let (pds_url, did_doc) = pds_client
139	        .discover_pds(did)
140	        .await
141	        .map_err(map_discovery_error)?;
142	    if did_doc.did != did {
143	        return Err(ConsentError::DidMismatch);
144	    }
145	    if !pds_url_is_safe(&pds_url) {
146	        return Err(ConsentError::UnsupportedHost);
147	    }
148	    Ok(pds_url)
149	}
