1	<script lang="ts">
2	  import { tick } from 'svelte';
3	  import {
4	    previewOAuthConsent,
5	    previewOAuthConsentByRequestId,
6	    confirmOAuthConsent,
7	    scanQrCode,
8	    cancelQrScan,
9	    isCodedError,
10	    type ConsentPreview,
11	    type ConsentError,
12	  } from '$lib/ipc';
13	  import { parseConsentQr } from '$lib/consent-qr';
14	  import { authenticateBiometric } from '$lib/biometric';
15	  import { describeScope } from '$lib/agent-scopes';
16	  import Button from '$lib/components/ui/Button.svelte';
17	  import TextField from '$lib/components/ui/TextField.svelte';
18	  import Spinner from '$lib/components/ui/Spinner.svelte';
19	  import ScreenHeader from '$lib/components/ui/ScreenHeader.svelte';
20	
21	  let {
22	    did,
23	    handle,
24	    onback,
25	    ondone,
26	  }: {
27	    did: string;
28	    /** The identity's handle, shown as "as @{handle}"; falls back to the DID when absent. */
29	    handle?: string;
30	    onback: () => void;
31	    /** Called after a recorded decision (approve or deny). */
32	    ondone: () => void;
33	  } = $props();
34	
35	  type Phase = 'enter' | 'loading' | 'review' | 'approving' | 'denying' | 'approved' | 'denied';
36	
37	  let phase = $state<Phase>('enter');
38	  let code = $state('');
39	  let codeError = $state<string | undefined>(undefined);
40	  let preview = $state<ConsentPreview | null>(null);
41	  /** Non-`atproto` scope tokens the user has left checked (scope reduction lives here). */
42	  let checked = $state<Set<string>>(new Set());
43	  let ceremonyError = $state<{ title: string; body: string } | null>(null);
44	
45	  // ── QR scan (Phase B: cross-device convenience channel) ──────────────────────
46	  // `scanning` makes the WebView see-through so the native camera the barcode-scanner plugin
47	  // renders BEHIND the web layer is visible; the overlay draws only the framing. A monotonic
48	  // `scanToken` supersedes an in-flight scan so a late-settling scanQrCode() (or a Cancel) can't
49	  // touch shared state. `scanHint` carries the "no camera / bad QR" fallback nudge to the typed code.
50	  let scanning = $state(false);
51	  let scanHint = $state<string | undefined>(undefined);
52	  let scanToken = 0;
53	  let overlayEl = $state<HTMLDivElement | undefined>();
54	  let triggerEl = $state<HTMLDivElement | undefined>();
55	
56	  const asWho = $derived(handle ? `@${handle}` : did);
57	  const clientLabel = $derived(preview?.clientName ?? preview?.clientId ?? 'an app');
58	  const originLabel = $derived(preview ? originOf(preview) : '');
59	  /** Non-`atproto` requested tokens, each with a plain-language description, for the checkboxes. */
60	  let optionalScopes = $derived(
61	    preview
62	      ? preview.requestedScope.filter((t) => t !== 'atproto').map((t) => describeScope(t))
63	      : []
64	  );
65	
66	  function originOf(p: ConsentPreview): string {
67	    if (p.origin) {
68	      try {
69	        return new URL(p.origin).host;
70	      } catch {
71	        return p.origin;
72	      }
73	    }
74	    try {
75	      return new URL(p.redirectUri).host;
76	    } catch {
77	      return p.redirectUri;
78	    }
79	  }
80	
81	  function errorCode(e: unknown): ConsentError['code'] | 'UNEXPECTED' {
82	    if (isCodedError(e)) return (e as ConsentError).code;
83	    return 'UNEXPECTED';
84	  }
85	
86	  function decisionFailure(codeName: string): { title: string; body: string } {
87	    switch (codeName) {
88	      case 'REQUEST_NOT_FOUND':
89	        return {
90	          title: 'This request expired',
91	          body: 'Sign-in requests are only valid for a few minutes. Return to the app and start again, then enter the new code.',
92	        };
93	      case 'ALREADY_RESOLVED':
94	        return {
95	          title: 'Already handled',
96	          body: 'This sign-in request has already been approved or denied. Return to the app and start again if needed.',
97	        };
98	      case 'APPROVAL_REJECTED':
99	        return {
100	          title: 'Your server rejected the approval',
101	          body: 'The signature could not be verified against your identity’s current keys. Nothing was granted.',
102	        };
103	      case 'RATE_LIMITED':
104	        return {
105	          title: 'Too many attempts',
106	          body: 'Your server paused sign-in checks for a few minutes. Wait, then try again.',
107	        };
108	      default:
109	        return {
110	          title: 'Could not complete the request',
111	          body: 'Your server could not record the decision. Nothing was granted — you can try again.',
112	        };
113	    }
114	  }
115	
116	  /** The verbatim granted-scope string the wallet signs: `atproto` (always) + every checked token. */
117	  function grantedScopeString(): string {
118	    if (!preview) return 'atproto';
119	    return preview.requestedScope
120	      .filter((t) => t === 'atproto' || checked.has(t))
121	      .join(' ');
122	  }
123	
124	  function toggle(token: string) {
125	    const next = new Set(checked);
126	    if (next.has(token)) next.delete(token);
127	    else next.add(token);
128	    checked = next;
129	  }
130	
131	  /** Accept a fetched preview: default scope reduction to "grant everything requested", then review. */
132	  function applyPreview(p: ConsentPreview) {
133	    preview = p;
134	    checked = new Set(p.requestedScope.filter((t) => t !== 'atproto'));
135	    phase = 'review';
136	  }
137	
138	  async function loadPreview() {
139	    codeError = undefined;
140	    ceremonyError = null;
141	    const trimmed = code.trim().toUpperCase();
142	    if (!trimmed) {
143	      codeError = 'Enter the code shown on the sign-in page.';
144	      return;
145	    }
146	    phase = 'loading';
147	    try {
148	      applyPreview(await previewOAuthConsent(did, trimmed));
149	      code = trimmed;
150	    } catch (e) {
151	      phase = 'enter';
152	      const c = errorCode(e);
153	      if (c === 'REQUEST_NOT_FOUND') {
154	        codeError = 'That code was not recognized or has expired. Check it and try again.';
155	      } else if (c === 'RATE_LIMITED') {
156	        ceremonyError = decisionFailure(c);
157	      } else {
158	        codeError = 'Could not reach your server. Check your connection and try again.';
159	      }
160	    }
161	  }
162	
163	  /** Scan a QR from the sign-in page: decode → extract `request_id` → verify server-side by that id
164	   *  (never trusting the QR contents for display) → same review → biometric → sign flow. */
165	  async function scan() {
166	    const token = ++scanToken;
167	    scanning = true;
168	    scanHint = undefined;
169	    codeError = undefined;
170	    ceremonyError = null;
171	    let text: string;
172	    try {
173	      text = await scanQrCode();
174	    } catch {
175	      // A cancelled/superseded scan isn't a real failure — leave the current UI alone.
176	      if (token !== scanToken) return;
177	      scanning = false;
178	      // No camera (simulator/desktop) or permission denied — the typed code is the path.
179	      scanHint = 'Camera scanning is unavailable here. Enter the code from the sign-in page below.';
180	      return;
181	    }
182	    // A newer scan or a Cancel superseded this one — don't touch shared state.
183	    if (token !== scanToken) return;
184	    scanning = false;
185	    const requestId = parseConsentQr(text);
186	    if (!requestId) {
187	      scanHint = 'That QR was not an Obsign sign-in code. Enter the code from the page below.';
188	      return;
189	    }
190	    phase = 'loading';
191	    try {
192	      applyPreview(await previewOAuthConsentByRequestId(did, requestId));
193	    } catch (e) {
194	      phase = 'enter';
195	      const c = errorCode(e);
196	      if (c === 'REQUEST_NOT_FOUND') {
197	        scanHint = 'That sign-in request expired. Reload the sign-in page and scan the new code.';
198	      } else if (c === 'RATE_LIMITED') {
199	        ceremonyError = decisionFailure(c);
200	      } else {
201	        scanHint = 'Could not reach your server. Check your connection and try again.';
202	      }
203	    }
204	  }
205	
206	  async function cancelScan() {
207	    // Supersede the in-flight scan — its result/error become no-ops via the token — and close the
208	    // overlay immediately for a responsive Cancel.
209	    scanToken++;
210	    scanning = false;
211	    try {
212	      await cancelQrScan();
213	    } catch {
214	      // best-effort — tearing the overlay down is what matters
215	    }
216	  }
217	
218	  // Scan mode makes the WebView see-through so the windowed native camera shows. base.css paints an
219	  // opaque ground on BOTH <html> (the anti-flash root paint) and <body>, so drop both to transparent
220	  // for the duration — otherwise the root <html> paint stays opaque behind the transparent body and
221	  // the camera is still hidden behind it (the admin-companion pair screen never hit this because its
222	  // base.css paints only <body>).
223	  $effect(() => {
224	    if (typeof document === 'undefined') return;
225	    document.documentElement.classList.toggle('scanning', scanning);
226	    document.body.classList.toggle('scanning', scanning);
227	    return () => {
228	      document.documentElement.classList.remove('scanning');
229	      document.body.classList.remove('scanning');
230	    };
231	  });
232	
233	  // Focus handoff: into the Cancel button when scan mode opens, back to the Scan button when it
234	  // closes (cancel, failed parse, or a bad QR) so focus never lands on the removed dialog. On a
235	  // successful scan the screen advances to the review phase and the trigger is gone — `host` is then
236	  // undefined and focus follows the newly-rendered review content, which is the desired handoff.
237	  let wasScanning = false;
238	  $effect(() => {
239	    const open = scanning;
240	    if (open === wasScanning) return;
241	    wasScanning = open;
242	    const host = open ? overlayEl : triggerEl;
243	    void tick().then(() => host?.querySelector<HTMLButtonElement>('button')?.focus());
244	  });
245	
246	  async function approve() {
247	    if (!preview) return;
248	    ceremonyError = null;
249	    phase = 'approving';
250	    try {
251	      // The biometric prompt is the authorization boundary: rejecting it aborts before any
252	      // signing or network call, so cancel truly means nothing was granted.
253	      await authenticateBiometric(`Sign in to ${clientLabel} as ${asWho}`);
254	    } catch {
255	      phase = 'review';
256	      return;
257	    }
258	    try {
259	      await confirmOAuthConsent(did, preview.requestId, preview.clientId, 'approve', grantedScopeString());
260	      phase = 'approved';
261	      setTimeout(() => ondone(), 1200);
262	    } catch (e) {
263	      phase = 'review';
264	      ceremonyError = decisionFailure(errorCode(e));
265	    }
266	  }
267	
268	  async function deny() {
269	    if (!preview) {
270	      onback();
271	      return;
272	    }
273	    ceremonyError = null;
274	    phase = 'denying';
275	    try {
276	      // Denial signs a terminal consent envelope, so it gates on biometrics too: a cancelled
277	      // prompt aborts before any signing or network call, exactly like the approval path.
278	      await authenticateBiometric(`Deny sign-in to ${clientLabel} as ${asWho}`);
279	    } catch {
280	      phase = 'review';
281	      return;
282	    }
283	    try {
284	      // Denial terminates the request on the server so the app stops waiting; it grants nothing.
285	      await confirmOAuthConsent(did, preview.requestId, preview.clientId, 'deny', '');
286	      phase = 'denied';
287	      setTimeout(() => ondone(), 1000);
288	    } catch (e) {
289	      phase = 'review';
290	      ceremonyError = decisionFailure(errorCode(e));
291	    }
292	  }
293	</script>
