/// Time-to-live of a pending wallet-consent request (~5 minutes, per the design).
const PENDING_REQUEST_TTL_SECS: i64 = 300;
/// How long an expired pending row lingers before opportunistic cleanup reclaims it, so the status
/// poll can still report `expired` for a while after the window closes.
const PENDING_REQUEST_CLEANUP_GRACE_SECS: i64 = 3600;

/// Reduce an `Origin`/`Referer` header to just scheme + host (+ port), discarding any path, query,
/// or fragment. The wallet only ever shows the requesting origin, and a full referring URL has no
/// business landing in the pending row or the audit log.
fn sanitize_origin(raw: &str) -> Option<String> {
    let parsed = url::Url::parse(raw).ok()?;
    let host = parsed.host_str()?;
    let scheme = parsed.scheme();
    Some(match parsed.port() {
        Some(port) => format!("{scheme}://{host}:{port}"),
        None => format!("{scheme}://{host}"),
    })
}

/// Fully-resolved parameters for the authorization consent page.
///
/// Constructed either directly from query params (non-PAR flow) or by looking up
/// the stored PAR request and deserializing its JSON (PAR flow via `request_uri`).
---

use common::{ApiError, ErrorCode};
use sqlx::Sqlite;

/// Whether `did` names a locally-hosted account in an active lifecycle — not deactivated,
/// suspended, or taken down. Executor-generic so callers can re-check inside a transaction; the
/// sovereign-session and wallet-consent proofs both gate on this before minting anything.
pub(crate) async fn active_local_account_exists<'e, E>(
    executor: E,
    did: &str,
) -> Result<bool, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM accounts WHERE did = ? \
         AND deactivated_at IS NULL AND suspended_at IS NULL AND taken_down_at IS NULL)",
    )
    .bind(did)
    .fetch_one(executor)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, account_did = %did, "failed to check local account lifecycle");
        ApiError::new(ErrorCode::InternalError, "failed to verify account")
    })
}

